pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(uint160(actor) > 0xFF);          // exclude precompiles: empty-data calls to them can revert
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);          // plain recipients only, so the ETH payout call succeeds
        amount = bound(amount, 1, 1e18);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        bool firstOk;
        vm.prank(actor);
        try c.withdrawAll() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk);

        bool secondOk;
        vm.prank(actor);
        try c.withdrawAll() { secondOk = true; } catch { secondOk = false; }
        // General rule: once all credit is paid out, a repeat withdrawAll is a harmless no-op and must succeed.
        // Bug: credit was not cleared, so the repeat withdrawal underflows `balance` and reverts.
        assertTrue(secondOk);
    }
}

