pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter attacker;

    function setUp() public { c = new C(); attacker = new Reverter(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(attacker), amount);

        // attacker deposits, then drains its credit
        vm.prank(address(attacker));
        c.deposit{value: amount}();
        vm.prank(address(attacker));
        c.withdrawAll();

        // now credit[attacker] == 0; a second withdrawAll must still succeed.
        // P: guard oCredit>0 is false, no external call -> succeeds.
        // M: guard oCredit>=0 always true, zero-value call to the reverting
        //    attacker fails -> require(callResult) reverts.
        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok, "withdrawAll with zero credit must not revert");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

