pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public { c = new C(); reverter = new Reverter(); }

    function testFuzz_property(uint256 amount) public {
        // Keep the domain wide but small enough that amount == 0 (the bug trigger) is found.
        amount = bound(amount, 0, 10);

        // Route all of c's interaction through the adversarial (reverting) counterparty.
        vm.startPrank(address(reverter));
        if (amount > 0) {
            vm.deal(address(reverter), amount);
            c.deposit{value: amount}();
        }
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // A caller (with zero credit when amount == 0) must always be able to complete withdrawAll.
        assertTrue(ok);
    }
}

