pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 callbackDeposit) public {
        amount = bound(amount, 1, 1 ether);
        callbackDeposit = bound(callbackDeposit, 1, 1 ether);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount + callbackDeposit + 1 ether);

        // attacker deposits `amount` as credit
        attacker.deposit{value: amount}();
        // record what the callback should deposit when paid
        attacker.setCallbackDeposit(callbackDeposit);

        bool ok;
        try attacker.withdraw() { ok = true; } catch { ok = false; }

        assertTrue(ok);
        // Rule: once withdrawAll succeeds, the caller's credit is fully consumed -> zero.
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

contract Attacker {
    C c;
    uint256 cb;

    constructor(C _c) { c = _c; }

    function setCallbackDeposit(uint256 x) external { cb = x; }

    function deposit() external payable {
        c.deposit{value: msg.value}();
    }

    function withdraw() external {
        c.withdrawAll();
    }

    receive() external payable {
        if (address(this).balance >= cb && cb > 0) {
            c.deposit{value: cb}();
        }
    }
}

