contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        bool ok;
        try a.go(amount) { ok = true; } catch { ok = false; }
        // General rule: a reentrant withdrawal must not be able to complete
