pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 redeposit) public {
        amount = bound(amount, 1, 1e18);
        redeposit = bound(redeposit, 1, 1e18);

        att = new Attacker(c);
        vm.deal(address(att), amount + redeposit);

        // deposit `amount`, withdraw it; during the external call the attacker
        // re-enters deposit with `redeposit` (deposit is not mutex-protected).
        att.attack(amount, redeposit);

        // General rule: once withdrawAll has completed successfully, the
        // contract owes the caller nothing — credit[caller] == 0, because the
        // reference zeroes credit after the external call returns. The mutant
        // zeroes credit before the call, so the re-entrant deposit of
        // `redeposit` is recorded into a fresh nonzero credit and survives.
        assertTrue(c.credit(address(att)) == 0);
    }
}

contract Attacker {
    C immutable target;
    uint256 reAmt;
    bool reentered;

    constructor(C t) { target = t; }

    function attack(uint256 amount, uint256 redeposit) external {
        reAmt = redeposit;
        target.deposit{value: amount}();
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered && reAmt > 0) {
            reentered = true;
            target.deposit{value: reAmt}();
        }
    }
}

