pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(c); }

    function testFuzz_property(uint256 d, uint256 f) public {
        // wide admissible domain: positive deposit d, external funding F >= d
        d = bound(d, 1, 1e18);
        f = bound(f, d, d + 1e18);

        // attacker deposits d (fuzzed) and gets paid via the callback
        vm.deal(address(attacker), d);
        attacker.deposit(d);

        // top the contract's balance up to the fuzzed value F; since F >= d,
        // in the reference the reentrant withdrawAll succeeds (double payout);
        // in the mutant the reentrant call is a silent no-op (single payout)
        vm.deal(address(c), f);

        attacker.attack();

        // Rule: when the reentrant withdrawal succeeds, both claims are paid,
        // so c's balance must end strictly below F. Reference: balance = F - d (< F).
        // Mutant: balance = F, which breaks the rule for every admissible input.
        assertTrue(address(c).balance != f);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    function deposit(uint256 amount) external payable {
        c.deposit{value: amount}();
    }

    receive() external payable {
        // reenter: in the reference this pays out again; in the mutant it is a no-op
        try c.withdrawAll() {} catch {}
    }

    function attack() external {
        try c.withdrawAll() {} catch {}
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);

        // adversarial re-entrant counterparty
        Attacker a = new Attacker(c);

        // innocent liquidity so the contract can honor payouts
        address pad = address(0xBEEF);
        vm.deal(pad, amount);
        vm.prank(pad);
        c.deposit{value: amount}();

        // attacker funds its own credit
        vm.deal(address(a), amount);
        a.fund(amount);

        uint256 before = address(c).balance;
        a.attack();

        // General rule: the contract never pays a user more than its credit;
        // re-entrant withdrawal must be blocked, so exactly `amount` leaves here.
        assertTrue(address(c).balance == before - amount);
    }
}

contract Attacker {
    C c;

    constructor(C _c) { c = _c; }

    function fund(uint256 amt) external {
        c.deposit{value: amt}();
    }

    function attack() external {
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter; must revert in the guarded (reference) contract
        (bool s, ) = address(c).call("");
        s; // ignore: in P this reverts, in M it succeeds
    }
}
